// =====================
// CONSTANTS
// =====================
const BCC_CHUNK_SIZE = 20; // recipients per BCC batch - lower this if your provider limits it

// =====================
// INPUTS
// =====================
const updates = $('Keep only recent updates')?.first()?.json?.output?.updates || [];
const sheetItems = $('Remove unsubscribed people').all() || [];

const LOGO_URL = 'YOUR_LOGO_IMAGE_URL';

const categories = Array.from(
  new Set(updates.flatMap(u => Array.isArray(u.Categories) ? u.Categories : []))
).filter(c => c && c.trim() !== '');

// =====================
// HELPERS
// =====================
function chunkArray(array, size) {
  const chunks = [];
  for (let i = 0; i < array.length; i += size) {
    chunks.push(array.slice(i, i + size));
  }
  return chunks;
}

// =====================
// BUILD EMAIL BODY
// =====================
const firstUpdate = updates[0] || {};
const introLine = updates.length > 0
  ? `The ${firstUpdate.department || 'Authority'} has issued a ${(firstUpdate.type || 'notice').toLowerCase()} on ${firstUpdate.Date || 'recent date'} regarding ${firstUpdate.Title || 'regulatory updates'}.`
  : 'Please find the latest regulatory updates below.';

const updateCards = updates.map(update => `
<div style="margin-bottom:16px; padding:16px 18px; background:#f9fafb; border-radius:6px; border-left:4px solid #1d4ed8;">
  <p style="margin:0 0 8px 0; font-size:15px; font-weight:bold; color:#1d4ed8;">
    ${update.department || ''} – ${update.Title || 'No Title'}
  </p>
  <p style="margin:4px 0; font-size:13px; color:#111827;"><strong>Date:</strong> ${update.Date || 'N/A'}</p>
  <p style="margin:4px 0; font-size:13px; color:#111827;"><strong>Type:</strong> ${update.type || 'N/A'}</p>
  <p style="margin:4px 0; font-size:13px; color:#111827;"><strong>Summary:</strong> ${update.Summary || 'N/A'}</p>
  <p style="margin:4px 0; font-size:13px; color:#111827;"><strong>Impact Area:</strong> ${update.impact_area || 'N/A'}</p>
  <p style="margin:4px 0; font-size:13px; color:#111827;"><strong>Action Required:</strong> ${update.ActionRequired || 'None'}</p>
  <a href="${update.SourceURL || '#'}" target="_blank"
     style="display:inline-block; margin-top:8px; font-size:13px; color:#2563eb; text-decoration:none;">
     Read Official Circular
  </a>
</div>
`).join('');

const body = `
<!DOCTYPE html>
<html>
<body style="font-family:Arial, sans-serif; background:#ffffff; padding:20px; margin:0;">
<div style="max-width:700px; margin:auto;">
  <div style="text-align:left; margin-bottom:20px; padding-bottom:16px; border-bottom:2px solid #e5e7eb;">
    <img src="${LOGO_URL}" alt="ELT Corporate Pvt. Ltd." style="height:55px; display:block;">
  </div>
  <p style="font-size:16px; font-weight:bold; color:#1d4ed8; margin-bottom:12px;">Dear Client,</p>
  <p style="font-size:14px; color:#111827; margin-bottom:16px;">${introLine}</p>
  <hr style="border:none; border-top:1px solid #e5e7eb; margin-bottom:16px;">
  <p style="font-size:14px; font-weight:bold; color:#111827; margin-bottom:12px;">Here are all the updates in this category:</p>
  ${updateCards}
  <hr style="border:none; border-top:1px solid #e5e7eb; margin:20px 0;">
  <p style="font-size:13px; color:#374151; line-height:1.8;">
    At <strong style="color:#1d4ed8; font-size:14px;">ELT Corporate Pvt. Ltd.</strong>, we understand how overwhelming regulatory updates can feel. Our team reviews the new rules in detail, highlights what's important, and ensures your compliance is handled smoothly.
    <a href="YOUR_WEBSITE_URL" target="_blank" style="color:#2563eb; text-decoration:none; font-weight:bold;">Click Here</a>
  </p>
  <p style="font-size:13px; color:#374151; line-height:1.6;">
    Reach out to us today and let us make compliance effortless and worry-free for you.
  </p>
  <p style="font-size:11px; color:#6b7280; margin-top:16px; text-align:center;">
    If you prefer not to receive such updates, simply reply to this email with
    <span style="color:#111827; font-weight:600;">"Not Interested"</span>.
  </p>
</div>
</body>
</html>`;

const subject = $('Keep only recent updates').first().json?.output?.subject || 'Regulatory Updates';

// =====================
// COLLECT ALL EMAIL CHUNKS — category wise
// =====================
const allChunks = [];

categories.forEach(category => {
  const matchedRows = sheetItems.filter(item =>
    (item.json?.Category || '').toLowerCase().trim() ===
    (category || '').toLowerCase().trim()
  );

  const emails = matchedRows
    .map(item => item.json?.Email)
    .filter(e => e && e.trim() !== '');

  if (emails.length === 0) return;

  chunkArray(emails, BCC_CHUNK_SIZE).forEach((chunk, index) => {
    allChunks.push({
      category,
      chunkIndex: index + 1,
      bccEmails: chunk,
      emailCount: chunk.length
    });
  });
});

// =====================
// ENFORCE 500/DAY HARD CAP — take first 500 only, skip rest
// Next week trigger will send fresh batch anyway
// =====================
let totalEmailCount = 0;
const cappedChunks = [];

for (const chunk of allChunks) {
  if (totalEmailCount + chunk.emailCount > DAILY_EMAIL_LIMIT) {
    // Hard stop — do not process any more chunks
    break;
  }
  cappedChunks.push(chunk);
  totalEmailCount += chunk.emailCount;
}

// =====================
// BUILD FINAL OUTPUT ITEMS
// =====================
const result = cappedChunks.map((chunk, i) => ({
  json: {
    _chunkNumber: i + 1,
    _totalChunks: cappedChunks.length,
    _totalEmailsThisRun: totalEmailCount,
    category: chunk.category,
    chunkIndex: chunk.chunkIndex,
    emailCount: chunk.emailCount,
    bcc: chunk.bccEmails.join(','),
    to: 'user@example.com',
    subject,
    body
  }
}));

// =====================
// SAFE FALLBACK
// =====================
if (result.length === 0) {
  return [{
    json: {
      to: '',
      bcc: '',
      subject,
      body,
      message: 'No matching recipients found or daily cap reached'
    }
  }];
}

return result;

const items = $input.all();
const allUpdates = [];

items.forEach(item => {
  if (item.json?.output?.updates && Array.isArray(item.json.output.updates)) {
    allUpdates.push(...item.json.output.updates);
  }
});

// =====================
// FILTER: only keep updates dated within the last 3 days
// =====================
const today = new Date();
const cutoffDate = new Date();
cutoffDate.setDate(today.getDate() - 3);

function parseDate(dateStr) {
  try {
    const date = new Date(dateStr.trim());
    return isNaN(date.getTime()) ? null : date;
  } catch (e) {
    return null;
  }
}

const filtered = allUpdates.filter(update => {
  if (!update.Date) return false;
  const updateDate = parseDate(update.Date);
  if (!updateDate) return false;
  return updateDate >= cutoffDate && updateDate <= today;
});

// =====================
// ALWAYS RETURN SOMETHING — keeps loop alive
// =====================
return [
  {
    json: {
      output: {
        updates: filtered, // empty array if nothing matched
        subject: $input.first().json?.output?.Subject ?? '',
        hasUpdates: filtered.length > 0, // flag to check downstream
        skipped: filtered.length === 0 // flag for "no relevant updates"
      }
    }
  }
];
